node -v && node --input-type=module -e '
import { checkSms } from "./bot.mjs";
const chi = (phone, extra = {}) => ({ phone, timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...extra });
const m = (to) => ({ kind: "marketing", body: "x", to });
const t = (to) => ({ kind: "transactional", body: "x", to });
const P = "+13125550142";
const cases = [
  ["example marketing 10:00 CDT allowed", m(chi(P)), new Date("2026-10-23T15:00:00Z"), {allowed:true,reason:null}],
  ["marketing 02:00 CDT quiet", m(chi(P)), new Date("2026-10-23T07:00:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["marketing 08:00 CDT allowed (start inclusive)", m(chi(P)), new Date("2026-10-23T13:00:00Z"), {allowed:true,reason:null}],
  ["marketing 21:00 CDT quiet (end exclusive)", m(chi(P)), new Date("2026-10-24T02:00:00Z"), {allowed:false,reason:"quiet_hours"}],
  ["marketing 08:00 CST allowed (winter DST)", m(chi(P)), new Date("2027-01-15T14:00:00Z"), {allowed:true,reason:null}],
  ["marketing no consent", m(chi(P,{marketingConsent:false})), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"marketing_consent_missing"}],
  ["marketing consent absent", m({phone:P,timeZone:"America/Chicago",optedOutAt:null}), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"marketing_consent_missing"}],
  ["marketing opted out", m(chi(P,{optedOutAt:"2026-10-01T12:00:00Z"})), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"opted_out"}],
  ["marketing opt-out field missing", m({phone:P,timeZone:"America/Chicago",marketingConsent:true}), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"opt_out_unknown"}],
  ["marketing bad opt-out timestamp", m(chi(P,{optedOutAt:"yesterday"})), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"invalid_opt_out_timestamp"}],
  ["marketing invalid zone", m(chi(P,{timeZone:"Mars/Olympus"})), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"invalid_time_zone"}],
  ["transactional at 03:00 CDT allowed despite no consent+opt-out", t({phone:P,timeZone:"America/Chicago",marketingConsent:false,optedOutAt:"2026-10-01T12:00:00Z"}), new Date("2026-10-23T08:00:00Z"), {allowed:true,reason:null}],
  ["transactional bad phone", t({phone:"3125550142",timeZone:"America/Chicago"}), new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"invalid_phone"}],
  ["unknown kind", {kind:"promo",body:"x",to:chi(P)}, new Date("2026-10-23T15:00:00Z"), {allowed:false,reason:"unknown_kind"}],
  ["invalid now", m(chi(P)), new Date("nope"), {allowed:false,reason:"invalid_now"}],
];
let bad = 0;
for (const [name, msg, now, want] of cases) {
  const got = checkSms(msg, now);
  const ok = got.allowed === want.allowed && got.reason === want.reason;
  if (!ok) bad++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
const reasons = cases.map(c => c[3].reason).filter(Boolean);
console.log("distinct block codes:", new Set(reasons).size, "of", reasons.length, "(opt-out-related codes are separate by design)");
console.log(bad === 0 ? "ALL PASS" : `${bad} FAILED`);
process.exitCode = bad ? 1 : 0;
'

